import { animateParallel, Block, Text } from "@prototyp/skeletor";
import { UploadSource } from "@unomed/react-native-matrix-sdk";
import { useAtomValue } from "jotai";
import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
import { checkPermission, PermissionType } from "modules/permissions/utils";
import { RecorderService } from "modules/recorder-player/services/recording-service-factory";
import { getTimeDuration, removeFile } from "modules/recorder-player/utils";
import { TimelineAtoms } from "modules/timeline/jotai";
import type { FC } from "react";
import { useEffect, useRef, useState } from "react";
import { Alert, AppState, Image, Linking, StyleSheet } from "react-native";
import RNBlobUtil from "react-native-blob-util";
import { Button } from "shared/components";
import { Colors } from "shared/styles";
import { offlineToastHelper } from "shared/utils";
import { AudioIndicator } from "../audio-indicator";

const playButtonTransition = animateParallel(
  { opacity: [0, 1], width: [0, 48] },
  { duration: 200, native: false },
);

interface Props {
  roomId: string;
  isRecording: boolean;
  isRecorded: boolean;
  message: string;
  setIsRecorded: (isRecorded: boolean) => void;
  setIsRecording: (isRecording: boolean) => void;
}

const normalizePath = (path: string) => path.replace("file://", "");

export const VoiceRecordButton: FC<Props> = ({
  roomId,
  isRecording,
  isRecorded,
  message,
  setIsRecorded,
  setIsRecording,
}) => {
  const durationMs = useRef(0);
  const [duration, setDuration] = useState(0);
  const recordingPath = useRef<string | null>(null);
  const [isSending, setIsSending] = useState(false);
  const replyPayload = useAtomValue(TimelineAtoms.replyPayload);

  const startRecording = async () => {
    try {
      const hasMic = await checkPermission(PermissionType.MICROPHONE);
      if (!hasMic) {
        Alert.alert(
          "Microphone permission required",
          "Please grant microphone permission to record voice messages.",
          [
            {
              text: "Cancel",
              style: "cancel",
            },
            {
              text: "Open settings",
              onPress: () => Linking.openSettings(),
            },
          ],
        );
        return;
      }

      RecorderService.createListener((e) => {
        setDuration(e.currentPosition);
        durationMs.current = e.currentPosition;
      });

      await RecorderService.start();
      setIsRecording(true);
      setIsRecorded(true);
    } catch (error) {
      offlineToastHelper("Failed to start recording");
      console.error(error);
    }
  };

  const stopRecording = async () => {
    try {
      const path = await RecorderService.stop();
      RecorderService.removeListener();
      recordingPath.current = normalizePath(path);
      setIsRecording(false);
    } catch (error) {
      offlineToastHelper("Failed to stop recording");
      console.error(error);
    }
  };

  const sendRecording = async () => {
    try {
      setIsSending(true);
      setIsRecorded(false);

      if (isRecording) await stopRecording();

      if (!recordingPath.current) return;

      const stats = await RNBlobUtil.fs.stat(recordingPath.current);

      const room = MatrixCore.instance?.getRoom(roomId);
      if (!room) return Promise.reject(new Error("Room not found"));
      const timeline = await room.timeline();

      timeline.sendAudio(
        {
          source: new UploadSource.File({
            filename: recordingPath.current.replace("file://", ""),
          }),
          caption: undefined,
          formattedCaption: undefined,
          mentions: undefined,
          inReplyTo: undefined,
        },
        {
          duration: durationMs.current,
          size: BigInt(stats.size || 0),
          mimetype: "audio/m4a",
        },
      );

      // Don't immediately delete the recording - the SDK needs it for upload
      // Clean up UI state but keep the file so it can be played while uploading
      setDuration(0);
      durationMs.current = 0;
      recordingPath.current = null;
    } catch (error) {
      offlineToastHelper("Failed to send voice message");
      console.error(error);
    } finally {
      setIsSending(false);
    }
  };

  const removeRecording = async () => {
    if (!recordingPath.current) return;
    await removeFile(recordingPath.current);
    setDuration(0);
    durationMs.current = 0;
    recordingPath.current = null;
  };

  const deleteRecording = async () => {
    try {
      if (isRecording) await stopRecording();
      await removeRecording();
      setIsRecorded(false);
    } catch {
      offlineToastHelper("Failed to delete recording");
    }
  };

  useEffect(() => {
    /**Stop the recording when the app goes to background */
    const listener = AppState.addEventListener("change", (nextAppState) => {
      if (nextAppState.match(/inactive|background/) && isRecording) {
        stopRecording();
      }
    });

    return () => listener.remove();
  }, [isRecording]);

  useEffect(() => {
    if (message || isRecording || isRecorded || replyPayload) {
      playButtonTransition.reverse();
    } else playButtonTransition.start();
  }, [message, isRecording, isRecorded, replyPayload]);

  return (
    <Block flexDirection="row" flex={isRecording || isRecorded ? 1 : 0} gap={8}>
      <Block
        height={48}
        align="center"
        justify="center"
        animations={playButtonTransition.animations}
      >
        <Button.Outline
          disabled={isSending}
          style={styles.container}
          onPress={startRecording}
        >
          <Image
            source={require("assets/icons/microphone.png")}
            style={styles.image}
            tintColor={Colors.white80}
          />
        </Button.Outline>
      </Block>
      {(isRecording || isRecorded) && (
        <Block flexDirection="row" flex={1} gap={8}>
          <Button.Wrapper
            disabled={isSending}
            style={styles.container}
            onPress={deleteRecording}
          >
            <Image
              source={require("assets/icons/trash.png")}
              tintColor={Colors.error}
              style={styles.image}
            />
          </Button.Wrapper>
          <Block
            flex={1}
            align="center"
            gap={12}
            flexDirection="row"
            height={44}
            paddings={[10, 16]}
            background={Colors.white20}
            border={{ borderRadius: 40 }}
          >
            <AudioIndicator runAnimation={isRecording} />
            <Text>{getTimeDuration(duration)}</Text>
          </Block>
          <Button.Wrapper
            style={styles.container}
            disabled={isSending}
            onPress={isRecording ? stopRecording : sendRecording}
          >
            <Block
              height={48}
              width={48}
              align="center"
              justify="center"
              background={isRecording ? Colors.white20 : Colors.primary}
              border={{
                borderRadius: 24,
              }}
            >
              <Image
                source={
                  isRecording
                    ? require("assets/icons/stop.png")
                    : require("assets/icons/paper-plane-right.png")
                }
                style={styles.image}
                tintColor={Colors.white80}
              />
            </Block>
          </Button.Wrapper>
        </Block>
      )}
    </Block>
  );
};

const styles = StyleSheet.create({
  container: {
    width: 48,
    height: 48,
    alignItems: "center",
    justifyContent: "center",
  },
  image: {
    width: 24,
    height: 24,
  },
});

