import {
  AVEncoderAudioQualityIOSType,
  createSound,
} from "react-native-nitro-sound";
import { removeFile } from "../utils";

export const RecordingServiceFactory = () => {
  const sound = createSound();

  return {
    start: () =>
      sound.startRecorder(undefined, {
        AVFormatIDKeyIOS: "mp4",
        AVEncoderAudioQualityKeyIOS: AVEncoderAudioQualityIOSType.high,
      }),
    stop: sound.stopRecorder,
    createListener: sound.addRecordBackListener,
    removeListener: sound.removeRecordBackListener,
    remove: (path: string) => removeFile(path),
  };
};

export const RecorderService = RecordingServiceFactory();
